script:
(function () {
  'use strict';
  // Two spouses who retire in different years: the "gap" years when one is retired and the other
  // still works, and how the order of withdrawals in those years changes what is left.
  // One row per year t = 0, 1, ... (your age = your age now + t) until your plan age.
  //   Working spouse: pay = salary x (1 + raise)^t; take-home = pay x (1 - own contribution%) x
  //     (1 - tax on pay); pay x (own% + match%) goes into their own account at year end.
  //   Social Security (today's $) from each claiming age, grown with inflation; it counts net of the
  //     withdrawal tax rate on 85% of it.
  //   From the first retirement on: spending x (1 + inflation)^t is paid at the start of the year.
  //     need = spending - take-home - net Social Security (a surplus is added to joint savings).
  //     Joint savings are spent with no tax. A retirement-account withdrawal that must deliver a net
  //     amount n is grossed up: gross = n / (1 - tax - 10% if the owner is 59 or younger).
  //     Gap years: only the retired spouse's accounts can be used; the order between them and joint
  //     savings is your choice. Both retired: joint savings or retirement accounts first (same
  //     choice), the older spouse's accounts before the younger's.
  //   Then joint savings grow at their return and retirement accounts at theirs.
  //   After-tax value = joint savings + retirement accounts x (1 - withdrawal tax rate).
  // Checked in Node (b8pay/tests/sg.test.js): 0% returns, inflation and raises with $100,000
  //   joint savings, $50,000 spending and a $30,000 take-home in the gap -> $20,000 a year from
  //   joint savings, gone after 5 years; with retirement accounts first at 20% tax the same $20,000
  //   costs $25,000 a year, or $28,571.43 with the 10% early-withdrawal tax (age 58); a surplus
  //   year adds to joint savings; contributions follow S x 1.06^n + C x (1.06^n - 1.02^n) / 0.04;
  //   with equal returns and no early-withdrawal tax both orders leave the same after-tax value.

  // --- calc start
  // p: age1, age2, retire1, retire2, salary1, salary2, save1, save2, match, bal1, bal2, joint,
  //    spend, ss1, ss2, ssAge1, ssAge2, payTax, wdTax, ret, jointRet, raise, inflation, planAge, order
  function simulate(p) {
    var acct = [p.bal1, p.bal2], joint = p.joint, rows = [];
    var T = p.planAge - p.age1;
    var res = { rows: rows, atBoth: null, atBothReal: null, atBothAfterTax: null, gapYears: 0, gapDrawn: 0,
                penalty: 0, shortfall: 0, runOutAge: null, jointOutAge: null, firstGap: null };
    for (var t = 0; t <= T; t++) {
      var ages = [p.age1 + t, p.age2 + t];
      var working = [ages[0] < p.retire1, ages[1] < p.retire2];
      var infl = Math.pow(1 + p.inflation, t), grow = Math.pow(1 + p.raise, t);
      var stage = working[0] && working[1] ? 'both' : (working[0] || working[1] ? 'gap' : 'retired');
      if (stage === 'retired' && res.atBoth === null) {
        res.atBoth = joint + acct[0] + acct[1];
        res.atBothReal = res.atBoth / infl;
        res.atBothAfterTax = (joint + (acct[0] + acct[1]) * (1 - p.wdTax)) / infl;
      }
      var pay = [working[0] ? p.salary1 * grow : 0, working[1] ? p.salary2 * grow : 0];
      var takeHome = pay[0] * (1 - p.save1) * (1 - p.payTax) + pay[1] * (1 - p.save2) * (1 - p.payTax);
      var ss = (ages[0] >= p.ssAge1 ? p.ss1 * infl : 0) + (ages[1] >= p.ssAge2 ? p.ss2 * infl : 0);
      var ssNet = ss * (1 - 0.85 * p.wdTax);
      var row = { t: t, ages: ages, stage: stage, working: working, takeHome: takeHome, ss: ss, spend: 0,
                  fromJoint: 0, fromAcct: 0, penalty: 0, shortfall: 0 };
      if (stage !== 'both') {
        var spend = p.spend * infl, need = spend - takeHome - ssNet;
        row.spend = spend; row.need = need;
        if (need < 0) { joint -= need; need = 0; }
        // retirement accounts that can be used: retired owners, older first
        var order = [0, 1].filter(function (i) { return !working[i]; })
                          .sort(function (a, b) { return ages[b] - ages[a]; });
        var fromJointFn = function () {
          var take = Math.min(joint, need); joint -= take; need -= take; row.fromJoint += take;
        };
        var fromAcctFn = function () {
          order.forEach(function (i) {
            if (need <= 0.005 || acct[i] <= 0) return;
            var pen = ages[i] <= 59 ? 0.10 : 0, keep = 1 - p.wdTax - pen;
            if (keep <= 0) return;
            var gross = Math.min(acct[i], need / keep);
            acct[i] -= gross; need -= gross * keep; row.fromAcct += gross;
            row.penalty += gross * pen;
          });
        };
        if (p.order === 'retire') { fromAcctFn(); fromJointFn(); } else { fromJointFn(); fromAcctFn(); }
        if (need > 0.005) { row.shortfall = need; res.shortfall += need; if (res.runOutAge === null) res.runOutAge = ages[0]; }
        res.penalty += row.penalty;
        if (joint <= 0.005 && res.jointOutAge === null && row.fromJoint > 0) res.jointOutAge = ages[0];
        if (stage === 'gap') {
          res.gapYears++;
          res.gapDrawn += row.fromJoint + row.fromAcct;
          if (res.firstGap === null) res.firstGap = row;
        }
      }
      joint *= 1 + p.jointRet;
      acct[0] = acct[0] * (1 + p.ret) + pay[0] * (p.save1 + p.match);
      acct[1] = acct[1] * (1 + p.ret) + pay[1] * (p.save2 + p.match);
      row.joint = joint; row.acct = acct[0] + acct[1]; row.total = joint + acct[0] + acct[1];
      rows.push(row);
    }
    res.endTotal = joint + acct[0] + acct[1];
    res.endAfterTaxReal = (joint + (acct[0] + acct[1]) * (1 - p.wdTax)) / Math.pow(1 + p.inflation, T + 1);
    return res;
  }
  // --- calc end

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function num(id) { var v = parseFloat(el(id).value); return isNaN(v) ? NaN : v; }
  function set(id, text) { var e = el(id); if (e) e.textContent = text; }
  function fmt(v) { return money.format(Math.abs(v) < 0.5 ? 0 : v); }
  function plural(n, word) { return n + ' ' + word + (n === 1 ? '' : 's'); }

  function read() {
    return {
      age1: Math.round(num('sgAge1')), age2: Math.round(num('sgAge2')), retire1: Math.round(num('sgRetire1')),
      retire2: Math.round(num('sgRetire2')), salary1: num('sgSalary1'), salary2: num('sgSalary2'),
      save1: num('sgSave1') / 100, save2: num('sgSave2') / 100, match: num('sgMatch') / 100,
      bal1: num('sgBal1'), bal2: num('sgBal2'), joint: num('sgJoint'), spend: num('sgSpend'),
      ss1: num('sgSs1'), ss2: num('sgSs2'), ssAge1: Math.round(num('sgSsAge1')), ssAge2: Math.round(num('sgSsAge2')),
      payTax: num('sgPayTax') / 100, wdTax: num('sgWdTax') / 100, ret: num('sgReturn') / 100,
      jointRet: num('sgJointReturn') / 100, raise: num('sgRaise') / 100, inflation: num('sgInflation') / 100,
      planAge: Math.round(num('sgPlanAge')), order: el('sgOrder').value === 'retire' ? 'retire' : 'joint'
    };
  }

  function invalid(p) {
    var all = Object.keys(p).filter(function (k) { return k !== 'order'; }).map(function (k) { return p[k]; });
    if (all.some(function (v) { return !isFinite(v); }) ||
        [p.salary1, p.salary2, p.bal1, p.bal2, p.joint, p.spend, p.ss1, p.ss2].some(function (v) { return v < 0 || v > 1e10; }) ||
        p.save1 < 0 || p.save2 < 0 || p.save1 > 1 || p.save2 > 1 || p.match < 0 || p.match > 0.25 ||
        p.payTax < 0 || p.payTax > 0.6 || p.wdTax < 0 || p.wdTax > 0.6 || p.ret < -0.1 || p.ret > 0.2 ||
        p.jointRet < -0.1 || p.jointRet > 0.2 || p.raise < 0 || p.raise > 0.15 || p.inflation < 0 || p.inflation > 0.1 ||
        p.ssAge1 < 62 || p.ssAge1 > 70 || p.ssAge2 < 62 || p.ssAge2 > 70) {
      return 'Check the amounts: $0 or more, rates within their ranges and Social Security claiming ages from 62 to 70.';
    }
    if (p.age1 < 30 || p.age1 > 85 || p.age2 < 30 || p.age2 > 85) return 'Enter ages from 30 to 85.';
    if (p.retire1 < p.age1 || p.retire2 < p.age2 || p.retire1 > 85 || p.retire2 > 85) return 'Each retirement age must be at least that person\'s age now (and at most 85). Use the age now if they have already retired.';
    if (p.planAge <= p.retire1 || p.planAge > 110 || p.planAge - p.age1 > 80) return 'Plan until an age above your retirement age, up to 110.';
    return '';
  }

  function update() {
    var p = read(), error = el('sgError'), msg = invalid(p);
    error.hidden = !msg;
    if (msg) { error.textContent = msg; return; }

    var r = simulate(p);
    var other = simulate(Object.assign({}, p, { order: p.order === 'joint' ? 'retire' : 'joint' }));
    var byOrder = p.order === 'joint' ? { joint: r, retire: other } : { joint: other, retire: r };

    var first1 = p.retire1 - p.age1, first2 = p.retire2 - p.age2;
    var youFirst = first1 < first2;
    set('sgAtBoth', r.atBoth === null ? 'Not before age ' + p.planAge : fmt(r.atBoth));
    set('sgAtBothReal', r.atBoth === null ? '–' : fmt(r.atBothReal));
    set('sgGap', r.gapYears ? plural(r.gapYears, 'year') : 'None');
    set('sgGapDrawn', fmt(r.gapDrawn));
    set('sgLasts', r.runOutAge === null ? 'Past age ' + p.planAge : 'Your age ' + r.runOutAge);
    set('sgGapPay', r.firstGap ? fmt(r.firstGap.takeHome) : '–');
    set('sgGapNeed', r.firstGap ? fmt(Math.max(0, r.firstGap.need)) : '–');
    set('sgPenalty', fmt(r.penalty));
    set('sgJointOut', p.joint <= 0 ? 'No joint savings' : r.jointOutAge === null ? 'No' : 'At your age ' + r.jointOutAge);

    var a = byOrder.joint, b = byOrder.retire, text;
    if (r.gapYears === 0) {
      text = 'You retire in the same year, so there are no gap years and the drawing order only affects the years after.';
    } else if (a.atBothAfterTax === null) {
      text = 'Compare the two orders in the table below.';
    } else {
      var diff = a.atBothAfterTax - b.atBothAfterTax;
      if (Math.abs(diff) < 50) text = 'Both drawing orders leave about the same after-tax savings when you have both retired.';
      else text = (diff > 0 ? 'Drawing joint savings first' : 'Drawing the retirement accounts first') + ' leaves ' + fmt(Math.abs(diff)) +
                  ' more in after-tax savings (today\'s dollars) when you have both retired.';
      if (Math.max(a.penalty, b.penalty) > 0.5) text += ' Part of the difference is the 10% tax on withdrawals before 59½.';
    }
    set('sgCompare', text);

    var notes = [];
    if (r.runOutAge !== null) notes.push('Savings run short at your age ' + r.runOutAge + '; spending not covered adds up to ' + fmt(r.shortfall) + ' in future dollars.');
    if (r.gapYears) notes.push((youFirst ? 'You retire' : 'Your spouse retires') + ' first, ' + plural(r.gapYears, 'year') + ' before ' + (youFirst ? 'your spouse' : 'you') + '.');
    var noteEl = el('sgNote');
    noteEl.hidden = notes.length === 0;
    noteEl.textContent = notes.join(' ');

    var ot = el('sgOrderTable');
    while (ot.firstChild) ot.removeChild(ot.firstChild);
    [['Drawn from savings in the gap', fmt(a.gapDrawn), fmt(b.gapDrawn)],
     ['Early-withdrawal tax paid', fmt(a.penalty), fmt(b.penalty)],
     ['After-tax savings when both retired (today\'s $)', a.atBothAfterTax === null ? '–' : fmt(a.atBothAfterTax), b.atBothAfterTax === null ? '–' : fmt(b.atBothAfterTax)],
     ['Savings last until', a.runOutAge === null ? 'Past age ' + p.planAge : 'Your age ' + a.runOutAge, b.runOutAge === null ? 'Past age ' + p.planAge : 'Your age ' + b.runOutAge],
     ['After-tax savings at the end of the plan (today\'s $)', fmt(a.endAfterTaxReal), fmt(b.endAfterTaxReal)]].forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (c, i) {
        var cell = document.createElement(i === 0 ? 'th' : 'td');
        if (i === 0) cell.setAttribute('scope', 'row');
        cell.textContent = c; tr.appendChild(cell);
      });
      ot.appendChild(tr);
    });

    var body = el('sgSchedule');
    while (body.firstChild) body.removeChild(body.firstChild);
    r.rows.forEach(function (row) {
      var stage = row.stage === 'both' ? 'Both working' : row.stage === 'retired' ? 'Both retired' :
                  (row.working[0] ? 'Spouse retired, you work' : 'You retired, spouse works');
      var tr = document.createElement('tr');
      [String(row.ages[0]), String(row.ages[1]), stage, fmt(row.takeHome), fmt(row.ss), row.stage === 'both' ? '–' : fmt(row.spend),
       fmt(row.fromJoint), fmt(row.fromAcct), fmt(row.total)].forEach(function (c) {
        var td = document.createElement('td'); td.textContent = c; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('sgForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
